/* SPDX-License-Identifier: Apache-2.0
 * Native GEOS 1.x RGB565 mode adapter.
 * Newly authored adapter; HostIf wire exchange follows supplied Apache-2.0
 * pcgeos Library/HostIf/hostif.asm and VGA16 DPI calculations.
 * GNU as --32; .code16; linked at the original driver's BSS/stack end.
 * Definitions KIND_BASEBOX, REQUEST_DPI, TARGET_WIDTH and TARGET_HEIGHT
 * are generated by build_vesa64k.py.
 */
.intel_syntax noprefix
.code16
.arch i286
.section .text
.global InitFar, ProbeFar, ProbeNear, SetupNear, HostCall
.global AdapterEnd, RequestedWidth, RequestedHeight, SelectedMode, UseHost
.equ MAX_WIDTH, 2040
.equ MAX_HEIGHT, 1536
.equ MAX_PITCH, 4080
.equ VESA_INFO, 0x6ae9
.equ MODE_INFO, 0x6beb
.equ OLD_VESA_MODE, 0x6be9
.equ OLD_HOST_VERSION, 0x6ceb

InitFar:
 push ax
 push cx
 push dx
 push bx
 push si
 push di
 push bp
 push es
 push ds
 call SetupNear
 jc InitFailed
 mov byte ptr cs:[0x6736], 1
 mov si, 0xffff
 push cs
 call LegacyPointer
 mov byte ptr cs:[0x6723], 1
 pop ds
 pop es
 pop bp
 pop di
 pop si
 pop bx
 pop dx
 pop cx
 pop ax
 clc
 retf
InitFailed:
 mov al, byte ptr cs:[0x6724]
 xor ah, ah
 int 0x10
 pop ds
 pop es
 pop bp
 pop di
 pop si
 pop bx
 pop dx
 pop cx
 pop ax
 stc
 retf

/* Native private probe and ordinary named-device test share this body.
 * AX=1 when present, AX=ffff when absent; never sets a video mode.
 */
ProbeFar:
 call ProbeNear
 retf
ProbeNear:
 push bx
 push cx
 push dx
 push si
 push di
 push bp
 push es
 push ds
 .if KIND_BASEBOX
 call ChooseBasebox
 .else
 call ChooseVesa
 .endif
 jc ProbeAbsent
 mov ax, 1
 jmp ProbeDone
ProbeAbsent:
 mov ax, 0xffff
ProbeDone:
 pop ds
 pop es
 pop bp
 pop di
 pop si
 pop dx
 pop cx
 pop bx
 clc
 ret

/* Set-device callback: preserve caller registers; CF reports failure. */
SetupNear:
 push ax
 push bx
 push cx
 push dx
 push si
 push di
 push bp
 push es
 push ds
 call ProbeNear
 cmp ax, 1
 jne SetupFailed
 cmp word ptr cs:[UseHost], 0
 je SetupUsingBios
 mov ax, 4
 mov si, word ptr cs:[RequestedWidth]
 mov bx, word ptr cs:[RequestedHeight]
 xor cx, cx
 xor dx, dx
 xor di, di
 call HostCall
 jc SetupFailed
 test bx, bx
 jz SetupFailed
 test bx, 0xc000
 jnz SetupFailed
 mov word ptr cs:[SelectedMode], bx
 call QueryVesaInfo
 jc SetupFailed
 .if KIND_BASEBOX
 /* Adopt the actual, possibly clamped, Basebox geometry. */
 call FetchModeInfo
 jc SetupFailed
 mov ax, word ptr cs:[MODE_INFO+18]
 test ax, ax
 jz SetupFailed
 cmp ax, MAX_WIDTH
 ja SetupFailed
 mov word ptr cs:[RequestedWidth], ax
 mov ax, word ptr cs:[MODE_INFO+20]
 test ax, ax
 jz SetupFailed
 cmp ax, MAX_HEIGHT
 ja SetupFailed
 mov word ptr cs:[RequestedHeight], ax
 call ValidateModeData
 .else
 call ValidateMode
 .endif
 jc SetupFailed
SetupUsingBios:
 mov ax, word ptr cs:[SelectedMode]
 mov word ptr cs:[OLD_VESA_MODE], ax
 /* Reuse the native VBE setter and banking setup, not the old HostIf stubs. */
 mov word ptr cs:[OLD_HOST_VERSION], 0
 call LegacySet
 jc SetupFailed
 mov ax, word ptr cs:[RequestedWidth]
 cmp word ptr cs:[0x0050], ax
 jne SetupFailed
 mov ax, word ptr cs:[RequestedHeight]
 cmp word ptr cs:[0x004e], ax
 jne SetupFailed
 mov word ptr cs:[0x0052], REQUEST_DPI
 mov word ptr cs:[0x0054], REQUEST_DPI
 mov byte ptr cs:[0x0065], 0x86
 pop ds
 pop es
 pop bp
 pop di
 pop si
 pop dx
 pop cx
 pop bx
 pop ax
 clc
 ret
SetupFailed:
 pop ds
 pop es
 pop bp
 pop di
 pop si
 pop dx
 pop cx
 pop bx
 pop ax
 stc
 ret

/* Fixed-size VESA target: enumerate the BIOS list; never guess mode IDs. */
ChooseVesa:
 mov word ptr cs:[UseHost], 0
 mov word ptr cs:[RequestedWidth], TARGET_WIDTH
 mov word ptr cs:[RequestedHeight], TARGET_HEIGHT
 call QueryVesaInfo
 jc VesaFallback
 mov ax, word ptr cs:[VESA_INFO+14]
 mov word ptr cs:[ModeListOffset], ax
 mov ax, word ptr cs:[VESA_INFO+16]
 mov word ptr cs:[ModeListSegment], ax
 or ax, word ptr cs:[ModeListOffset]
 jz VesaFallback
 mov word ptr cs:[ModesRemaining], 512
VesaLoop:
 mov ax, word ptr cs:[ModeListSegment]
 mov es, ax
 mov di, word ptr cs:[ModeListOffset]
 mov ax, word ptr es:[di]
 cmp ax, 0xffff
 je VesaFallback
 add word ptr cs:[ModeListOffset], 2
 jc VesaFallback
 test ax, 0xc000
 jnz VesaNext
 mov word ptr cs:[SelectedMode], ax
 call ValidateMode
 jnc VesaPresent
VesaNext:
 dec word ptr cs:[ModesRemaining]
 jnz VesaLoop
 jmp VesaFallback
VesaPresent:
 clc
 ret
VesaFallback:
 call DetectBasebox
 jc ChooseFailure
 mov word ptr cs:[UseHost], 1
 clc
 ret

/* Basebox startup resolution is fixed for these VESA variants. */
ChooseBasebox:
 mov word ptr cs:[UseHost], 1
 call DetectBasebox
 jc ChooseFailure
 mov word ptr cs:[RequestedWidth], TARGET_WIDTH
 mov word ptr cs:[RequestedHeight], TARGET_HEIGHT
 clc
 ret
ChooseFailure:
 stc
 ret

DetectBasebox:
 mov ax, 98
 mov si, 1
 xor bx, bx
 xor cx, cx
 xor dx, dx
 xor di, di
 call HostCall
 jc DetectFailure
 cmp si, 0x4f58
 jne DetectFailure
 cmp bx, 0x4542
 jne DetectFailure
 cmp cx, 0x4153
 jne DetectFailure
 cmp dx, 0x3242
 jne DetectFailure
 cmp di, 1
 jb DetectFailure
 clc
 ret
DetectFailure:
 stc
 ret

QueryVesaInfo:
 push cs
 pop es
 mov di, VESA_INFO
 /* Request the original 256-byte VBE information block. */
 mov word ptr es:[di], 0
 mov word ptr es:[di+2], 0
 mov ax, 0x4f00
 int 0x10
 cmp ax, 0x004f
 jne ValidationFailure
 cmp word ptr cs:[VESA_INFO], 0x4556
 jne ValidationFailure
 cmp word ptr cs:[VESA_INFO+2], 0x4153
 jne ValidationFailure
 cmp word ptr cs:[VESA_INFO+4], 0x0102
 jb ValidationFailure
 mov ax, word ptr cs:[VESA_INFO+18]
 test ax, ax
 jz ValidationFailure
 mov word ptr cs:[VramUnits], ax
 clc
 ret

/* Validate every renderer assumption before native setup divides by gran. */
ValidateMode:
 call FetchModeInfo
 jc ValidationFailure
ValidateModeData:
 mov ax, word ptr cs:[RequestedWidth]
 test ax, ax
 jz ValidationFailure
 cmp ax, MAX_WIDTH
 ja ValidationFailure
 mov ax, word ptr cs:[RequestedHeight]
 test ax, ax
 jz ValidationFailure
 cmp ax, MAX_HEIGHT
 ja ValidationFailure
 mov ax, word ptr cs:[MODE_INFO]
 and ax, 0x0019
 cmp ax, 0x0019
 jne ValidationFailure
 mov ax, word ptr cs:[RequestedWidth]
 cmp word ptr cs:[MODE_INFO+18], ax
 jne ValidationFailure
 mov ax, word ptr cs:[RequestedHeight]
 cmp word ptr cs:[MODE_INFO+20], ax
 jne ValidationFailure
 cmp byte ptr cs:[MODE_INFO+24], 1
 jne ValidationFailure
 cmp byte ptr cs:[MODE_INFO+25], 16
 jne ValidationFailure
 cmp byte ptr cs:[MODE_INFO+27], 6
 jne ValidationFailure
 cmp word ptr cs:[MODE_INFO+31], 0x0b05
 jne ValidationFailure
 cmp word ptr cs:[MODE_INFO+33], 0x0506
 jne ValidationFailure
 cmp word ptr cs:[MODE_INFO+35], 0x0005
 jne ValidationFailure
 mov ax, word ptr cs:[RequestedWidth]
 shl ax, 1
 mov bx, word ptr cs:[MODE_INFO+16]
 cmp bx, ax
 jb ValidationFailure
 cmp bx, MAX_PITCH
 ja ValidationFailure
 test bl, 1
 jnz ValidationFailure
 mov ax, bx
 mul word ptr cs:[RequestedHeight]
 cmp dx, word ptr cs:[VramUnits]
 ja ValidationFailure
 jb CapacityOkay
 test ax, ax
 jnz ValidationFailure
CapacityOkay:
 cmp word ptr cs:[MODE_INFO+6], 64
 jne ValidationFailure
 mov cx, word ptr cs:[MODE_INFO+4]
 test cx, cx
 jz ValidationFailure
 cmp cx, 64
 ja ValidationFailure
 xor dx, dx
 mov ax, 64
 div cx
 test dx, dx
 jnz ValidationFailure
 mov al, byte ptr cs:[MODE_INFO+2]
 and al, 3
 cmp al, 3
 jne ReadBankB
 cmp word ptr cs:[MODE_INFO+8], 0
 je ValidationFailure
 jmp CheckWrite
ReadBankB:
 mov al, byte ptr cs:[MODE_INFO+3]
 and al, 3
 cmp al, 3
 jne ValidationFailure
 cmp word ptr cs:[MODE_INFO+10], 0
 je ValidationFailure
CheckWrite:
 mov al, byte ptr cs:[MODE_INFO+2]
 and al, 5
 cmp al, 5
 jne WriteBankB
 cmp word ptr cs:[MODE_INFO+8], 0
 je ValidationFailure
 jmp ValidationSuccess
WriteBankB:
 mov al, byte ptr cs:[MODE_INFO+3]
 and al, 5
 cmp al, 5
 jne ValidationFailure
 cmp word ptr cs:[MODE_INFO+10], 0
 je ValidationFailure
ValidationSuccess:
 clc
 ret
ValidationFailure:
 stc
 ret

FetchModeInfo:
 push cs
 pop es
 mov di, MODE_INFO
 mov cx, word ptr cs:[SelectedMode]
 mov ax, 0x4f01
 int 0x10
 cmp ax, 0x004f
 jne ValidationFailure
 clc
 ret

/* Synchronous HostIf transaction. Preserve BP and interrupt-enable state. */
HostCall:
 pushf
 cli
 push bp
 mov bp, dx
 mov dx, 0x38ff
 push ax
 in ax, dx
 pop ax
 out dx, ax
 mov ax, si
 out dx, ax
 mov ax, bx
 out dx, ax
 mov ax, cx
 out dx, ax
 mov ax, bp
 out dx, ax
 mov ax, di
 out dx, ax
 in ax, dx
 mov di, ax
 in ax, dx
 mov bp, ax
 in ax, dx
 mov cx, ax
 in ax, dx
 mov bx, ax
 in ax, dx
 mov si, ax
 in ax, dx
 mov dx, bp
 pop bp
 popf
 test ax, ax
 jnz HostFailure
 clc
 ret
HostFailure:
 stc
 ret

/* Explicit relative calls into the unchanged native renderer. */
LegacySet:
 .byte 0xe8
 .word 0x625c - . - 2
 ret
LegacyPointer:
 .byte 0xe9
 .word 0x1583 - . - 2

.balign 2
RequestedWidth: .word 0
RequestedHeight: .word 0
SelectedMode: .word 0
UseHost: .word 0
ModeListOffset: .word 0
ModeListSegment: .word 0
ModesRemaining: .word 0
VramUnits: .word 0
AdapterEnd:
